     BOOST_CHECK_EQUAL(psbt.outputs.size(), 2);
@@ -329,10 +335,10 @@ BOOST_AUTO_TEST_CASE(psbt_merge_fallback_locktime)
     PartiallySignedTransaction psbt1(mtx, /*version*/2);
