@@ -370,43 +376,43 @@ BOOST_AUTO_TEST_CASE(psbt_merge_modifiable)
     BOOST_CHECK(!psbt1.m_tx_modifiable.has_value());

     psbt1.m_tx_modifiable.emplace();
